// ❌ Object dependency được TẠO MỚI sau mỗi lần render
function UserProfile({ userId }: { userId: string }) {
  const [user, setUser] = useState<User | null>(null);

  // Object literal → tham chiếu MỚI mỗi render
  const options = { id: userId, detail: 'full' as const };

  useEffect(() => {
    fetch(`https://api.app.com/users/${options.id}`, {
      headers: { 'X-Detail': options.detail },
    })
      .then((res) => res.json())
      .then(setUser); // setUser → re-render → options mới → effect lại chạy
  }, [options]); // ❌ deps chứa object unstable — so sánh bằng ===

  return <ProfileCard user={user} />;
}

