// ❌ Closure chốt state CŨ tại thời điểm mount
function LikeCounter({ postId }: { postId: string }) {
  const [likes, setLikes] = useState(0);

  useEffect(() => {
    // Snapshot: likes = 0 bị 'đóng băng' vào closure này
    const timer = setTimeout(() => {
      fetch(`/api/posts/${postId}/sync`, {
        method: 'POST',
        body: JSON.stringify({ likes }), // ❌ mãi mãi là 0
      });
    }, 30_000);

    window.addEventListener('online', () => {
      navigator.sendBeacon('/api/analytics', String(likes)); // cũng là 0
    });

    return () => clearTimeout(timer);
  }, []); // ❌ đọc `likes` nhưng deps rỗng

  return <button onClick={() => setLikes((n) => n + 1)}>❤️ {likes}</button>;
}

