// ✅ Không đọc state trực tiếp trong closure — đọc qua updater hoặc ref

// 1) Cập nhật state: luôn dùng dạng hàm để nhận giá trị mới nhất
setLikes((prev) => prev + 1);

// 2) Timer/listener cần giá trị hiện tại → ref làm cầu nối
const likesRef = useRef(0);
useEffect(() => {
  likesRef.current = likes; // đồng bộ sau MỖI render
}, [likes]);

useEffect(() => {
  const timer = setTimeout(() => {
    fetch(`/api/posts/${postId}/sync`, {
      method: 'POST',
      body: JSON.stringify({ likes: likesRef.current }), // ✅ luôn fresh
    });
  }, 30_000);
  return () => clearTimeout(timer);
}, [postId]);

