// ❌ setInterval KHÔNG có clearInterval
function LiveTicker({ symbol }: { symbol: string }) {
  const [price, setPrice] = useState<number>(0);

  useEffect(() => {
    // Timer này sống MÃI MÃI — không ai giữ id của nó
    setInterval(() => {
      fetch(`/api/price/${symbol}`)
        .then((r) => r.json())
        .then((data) => setPrice(data.price));
    }, 1000);
    // ❌ Thiếu: return () => clearInterval(id);
  }, [symbol]);

  return <span className="tabular-nums">{price.toFixed(2)}$</span>;
}

